$ErrorActionPreference='Stop';$server=Split-Path $PSScriptRoot;. ([ScriptBlock]::Create((Get-Content -Raw -Encoding UTF8 (Join-Path $server 'orchestrator\TaskEngine.ps1'))));$task=[pscustomobject]@{attempt=1;max_attempts=3};if((Get-AI5FailureAction $task 'timeout')-ne'RETRY_CODEX'){throw'retry failed'};if((Get-AI5FailureAction $task 'unknown_cause')-ne'REROUTE_CLAUDE'){throw'claude reroute failed'};$task.attempt=3;if((Get-AI5FailureAction $task 'timeout')-ne'FAILED'){throw'max attempt failed'};'TASK_ENGINE_TESTS_OK'
